from dataclasses import dataclass
from typing import List

@dataclass(frozen=True)
class Transreal:
    kind: str          # "fin", "pinf", "ninf", "phi"
    value: float = 0.0
    def __repr__(self) -> str:
        return {"pinf": "+inf", "ninf": "-inf", "phi": "PHI"}.get(
            self.kind, str(self.value))
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Transreal): return NotImplemented
        return self.kind == other.kind and (self.kind != "fin" or self.value == other.value)
    def __hash__(self) -> int:
        return hash((self.kind, self.value if self.kind == "fin" else 0.0))

def real(x: float) -> Transreal: return Transreal("fin", float(x))
PINF, NINF, PHI = Transreal("pinf"), Transreal("ninf"), Transreal("phi")
ZERO, ONE = real(0.0), real(1.0)

def _sign(t: Transreal) -> int:
    if t.kind == "pinf": return 1
    if t.kind == "ninf": return -1
    return (t.value > 0) - (t.value < 0)

def neg(x: Transreal) -> Transreal:
    if x.kind == "phi": return PHI
    if x.kind == "pinf": return NINF
    if x.kind == "ninf": return PINF
    return real(-x.value)

def recip(x: Transreal) -> Transreal:
    if x.kind == "phi": return PHI
    if x.kind in ("pinf", "ninf"): return ZERO
    return PINF if x.value == 0.0 else real(1.0 / x.value)

def add(x: Transreal, y: Transreal) -> Transreal:
    if x.kind == "phi" or y.kind == "phi": return PHI
    if x.kind == "fin" and y.kind == "fin": return real(x.value + y.value)
    xi, yi = x.kind in ("pinf","ninf"), y.kind in ("pinf","ninf")
    if xi and yi: return PHI if x.kind != y.kind else x
    return x if xi else y

def mul(x: Transreal, y: Transreal) -> Transreal:
    if x.kind == "phi" or y.kind == "phi": return PHI
    if x.kind == "fin" and y.kind == "fin": return real(x.value * y.value)
    sx, sy = _sign(x), _sign(y)
    if sx == 0 or sy == 0: return PHI
    return PINF if sx * sy > 0 else NINF

def sub(x, y): return add(x, neg(y))
def div(x, y): return mul(x, recip(y))

if __name__ == "__main__":
    print("1/0     =", div(ONE, ZERO))
    print("-1/0    =", div(neg(ONE), ZERO))
    print("0/0     =", div(ZERO, ZERO))
    print("inf-inf =", sub(PINF, PINF))
    print("0*inf   =", mul(ZERO, PINF))
    tests = [real(-2), real(-1), ZERO, real(1), NINF, PHI, PINF]
    print("PHI absorbing:", all(add(PHI, t) == PHI and mul(PHI, t) == PHI for t in tests))

