from typing import Union, Tuple

Expr = Union[Transreal, Tuple]  # ("add", l, r) | ("mul", l, r) | ("neg", x) | ("recip", x)

def evaluate(e: Expr) -> Transreal:
    if isinstance(e, Transreal):
        return e
    op = e[0]
    if op == "neg":   return neg(evaluate(e[1]))
    if op == "recip": return recip(evaluate(e[1]))
    a, b = evaluate(e[1]), evaluate(e[2])
    return add(a, b) if op == "add" else mul(a, b)

