import itertools
from typing import Callable, List, Optional, Tuple

S: List[Transreal] = [real(-2), real(-1), ZERO, real(1), real(2), NINF, PHI, PINF]

def audit(lhs: Callable[..., Transreal], rhs: Callable[..., Transreal],
          arity: int) -> Optional[Tuple[Transreal, ...]]:
    for xs in itertools.product(S, repeat=arity):
        if lhs(*xs) != rhs(*xs):
            return xs
    return None

if __name__ == "__main__":
    # distributivity: a*(b+c) vs a*b+a*c
    w = audit(lambda a,b,c: mul(a, add(b,c)),
              lambda a,b,c: add(mul(a,b), mul(a,c)), 3)
    print("distributivity refuted by:", w)
    # annihilation: 0*x vs 0
    w = audit(lambda x: mul(ZERO, x), lambda x: ZERO, 1)
    print("annihilation refuted by:", w)

